import{_ as d,a as e,c as r,ac as a}from"./chunks/framework.BSuaGltH.js";const h=JSON.parse('{"title":"MySQL 基础概念对照 · 字符集至其他类似的数据库","description":"MySQL 事务、引擎、索引、字符集与数据类型对照。","frontmatter":{"title":"MySQL 基础概念对照 · 字符集至其他类似的数据库","description":"MySQL 事务、引擎、索引、字符集与数据类型对照。","splitFrom":"middleware/mysql/plus/subjects/mysql-base.md","showdocs":{"topics":[{"id":"mysql","title":"MySQL","link":"/topics/mysql/"}],"kind":"知识专题","scope":"general","audience":"general","group":"数据库与存储","seriesTitle":"MySQL 基础概念对照","summary":"MySQL 事务、引擎、索引、字符集与数据类型对照。","status":"active","related":[{"title":"01 · 连接数据库与准备练习数据","link":"/middleware/mysql/base/mysql-crash-course-2/01-start","kind":"知识专题","scope":"general","audience":"general"},{"title":"02 · 检索、排序与条件过滤","link":"/middleware/mysql/base/mysql-crash-course-2/02-filtering","kind":"知识专题","scope":"general","audience":"general"},{"title":"03 · 计算、汇总与多表查询","link":"/middleware/mysql/base/mysql-crash-course-2/03-querying","kind":"知识专题","scope":"general","audience":"general"},{"title":"04 · 数据写入、表结构与视图","link":"/middleware/mysql/base/mysql-crash-course-2/04-tables","kind":"知识专题","scope":"general","audience":"general"},{"title":"05 · 存储程序与事务边界","link":"/middleware/mysql/base/mysql-crash-course-2/05-programming","kind":"知识专题","scope":"general","audience":"general"}],"prev":{"text":"MySQL 基础概念对照 · MySQL至索引","link":"/middleware/mysql/plus/subjects/mysql-base-part-01"},"next":{"text":"MySQL 数据库与表操作","link":"/middleware/mysql/plus/subjects/mysql-operate"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"MySQL 基础概念对照 · MySQL至索引","link":"/middleware/mysql/plus/subjects/mysql-base-part-01"},"next":{"text":"MySQL 数据库与表操作","link":"/middleware/mysql/plus/subjects/mysql-operate"}},"headers":[],"relativePath":"middleware/mysql/plus/subjects/mysql-base-part-02.md","filePath":"middleware/mysql/plus/subjects/mysql-base-part-02.md"}'),s={name:"middleware/mysql/plus/subjects/mysql-base-part-02.md"};function l(o,t,i,n,c,m){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="mysql-基础概念对照-·-字符集至其他类似的数据库" tabindex="-1">MySQL 基础概念对照 · 字符集至其他类似的数据库 <a class="header-anchor" href="#mysql-基础概念对照-·-字符集至其他类似的数据库" aria-label="Permalink to &quot;MySQL 基础概念对照 · 字符集至其他类似的数据库&quot;">​</a></h1><p><a href="/middleware/mysql/plus/subjects/mysql-base">返回分篇目录</a></p><h2 id="字符集" tabindex="-1">字符集 <a class="header-anchor" href="#字符集" aria-label="Permalink to &quot;字符集 {#字符集}&quot;">​</a></h2><p>以下按 MySQL 8.4 的产品名称区分编码与字符集，不按“中文/英文”选择。见<a href="https://dev.mysql.com/doc/refman/8.4/en/charset-unicode.html" target="_blank" rel="noopener noreferrer">官方 Unicode 对照</a>。</p><table tabindex="0"><thead><tr><th>名称</th><th>含义与边界</th></tr></thead><tbody><tr><td>UTF-8</td><td>通用 Unicode 编码；不是只能编码三个字节的字符</td></tr><tr><td>MySQL <code>utf8mb4</code></td><td>完整的 UTF-8 编码，每个字符1～4字节，可表示补充字符</td></tr><tr><td>MySQL <code>utf8</code> / <code>utf8mb3</code></td><td>8.4中前者是后者的弃用别名，仅支持BMP字符，每字符1～3字节；新定义显式选utf8mb4</td></tr><tr><td><code>gbk</code></td><td>中文编码，是否适合取决于实际字符需求和系统互通</td></tr><tr><td><code>latin1</code></td><td>单字节字符集，不能覆盖全部Unicode字符</td></tr><tr><td><code>utf16</code></td><td>每字符2或4字节；不能一概说每字符16位</td></tr></tbody></table><h2 id="数据类型" tabindex="-1">数据类型 <a class="header-anchor" href="#数据类型" aria-label="Permalink to &quot;数据类型 {#数据类型}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>数据类型</th><th>描述</th><th>存储范围</th><th>大小</th><th>Go</th></tr></thead><tbody><tr><td>INT</td><td>整数类型，通常用于存储整数值</td><td>-2147483648 到 2147483647</td><td>4 字节</td><td>int32</td></tr><tr><td>BIGINT</td><td>大整数类型，用于存储较大的整数值</td><td>-9223372036854775808 到 9223372036854775807</td><td>8 字节</td><td>int64</td></tr><tr><td>FLOAT</td><td>单精度浮点数类型，用于存储小数值</td><td>约7位十进制有效数字（非小数位数）</td><td>4 字节</td><td>float32</td></tr><tr><td>DOUBLE</td><td>双精度浮点数类型，用于存储双精度小数值</td><td>约15位十进制有效数字（非小数位数）</td><td>8 字节</td><td>float64</td></tr><tr><td>DECIMAL(M, D)</td><td>定点数类型，用于存储精确的小数值</td><td>M为总精度，D为小数位；如DECIMAL(5,2)范围-999.99～999.99</td><td>依赖于 M 和 D</td><td>依驱动/精确数值方案</td></tr><tr><td>CHAR(N)</td><td>定长字符串类型，用于存储固定长度的字符串</td><td>最大长度为 N</td><td>字符长度N；字节数依字符集与长度前缀而异</td><td>string</td></tr><tr><td>VARCHAR(N)</td><td>变长字符串类型，用于存储可变长度的字符串</td><td>最大长度为 N</td><td>字符长度N；字节数依字符集与长度前缀而异</td><td>string</td></tr><tr><td>TEXT</td><td>变长字符串类型，用于存储较长的文本数据</td><td>最大长度为 65,535 字节</td><td>最大为 65,535 字节</td><td>string</td></tr><tr><td>DATE</td><td>日期类型，用于存储日期值</td><td>&#39;1000-01-01&#39; 到 &#39;9999-12-31&#39;</td><td>3 字节</td><td>依驱动配置</td></tr><tr><td>TIME</td><td>时间类型，用于存储时间值</td><td>&#39;-838:59:59&#39; 到 &#39;838:59:59&#39;</td><td>3 字节</td><td>依驱动配置</td></tr><tr><td>DATETIME</td><td>日期时间类型，用于存储日期和时间值</td><td>&#39;1000-01-01 00:00:00&#39; 到 &#39;9999-12-31 23:59:59&#39;</td><td>5字节基础存储，另加小数秒空间</td><td>依驱动配置</td></tr><tr><td>TIMESTAMP</td><td>时间戳类型，用于存储日期和时间值</td><td>&#39;1970-01-01 00:00:01&#39; 到 &#39;2038-01-19 03:14:07&#39;</td><td>4 字节</td><td>time.Time</td></tr><tr><td>BOOLEAN</td><td>布尔类型，用于存储逻辑值</td><td>TRUE 或 FALSE</td><td>1 字节</td><td>bool</td></tr></tbody></table><p>TIME、DATETIME、TIMESTAMP 的基础存储随小数秒精度增加额外空间，见<a href="https://dev.mysql.com/doc/refman/8.4/en/storage-requirements.html" target="_blank" rel="noopener noreferrer">官方存储要求</a>。类型表依据<a href="https://dev.mysql.com/doc/refman/8.4/en/fixed-point-types.html" target="_blank" rel="noopener noreferrer">DECIMAL精度</a>与<a href="https://dev.mysql.com/doc/refman/8.4/en/char.html" target="_blank" rel="noopener noreferrer">CHAR/VARCHAR字符长度</a>。<code>Go</code>列只是应用侧选择提示，不是数据库自动映射；NULL、UNSIGNED、驱动参数和SQL TIME的时长语义都需单独处理。</p><h2 id="主键-外键" tabindex="-1">主键&amp;外键 <a class="header-anchor" href="#主键-外键" aria-label="Permalink to &quot;主键&amp;外键 {#主键-外键}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>特点</th><th>主键</th><th>外键</th></tr></thead><tbody><tr><td>定义</td><td>用于唯一标识表中的每一行数据的字段，每张表只能有一个主键</td><td>用于建立表与表之间的关联关系，指向另一张表的主键或唯一键</td></tr><tr><td>唯一性</td><td>主键值在表中必须唯一，不允许为空</td><td>外键值可以为空，可以重复，但必须与关联表的主键值相对应</td></tr><tr><td>数据类型</td><td>通常为数值类型或字符串类型，与业务无关</td><td>与关联表的主键数据类型一致</td></tr><tr><td>作用</td><td>保证表中每一行数据的唯一性，可以用于快速定位数据</td><td>建立表与表之间的关联关系，确保数据的一致性和完整性</td></tr><tr><td>定义方式</td><td>可以在表的创建过程中使用 <code>PRIMARY KEY</code> 关键字来定义主键</td><td>通常在表的创建过程中使用 <code>FOREIGN KEY</code> 关键字来定义外键</td></tr><tr><td>示例</td><td>用户表中的用户 ID 字段可以作为主键，保证每个用户 ID 的唯一性</td><td>订单表中的用户 ID 字段可以作为外键，与用户表中的用户 ID 建立关联</td></tr></tbody></table><h2 id="其他类似的数据库" tabindex="-1">其他类似的数据库 <a class="header-anchor" href="#其他类似的数据库" aria-label="Permalink to &quot;其他类似的数据库 {#其他类似的数据库}&quot;">​</a></h2><blockquote><p>在数据处理方案中，有几种与 MySQL 类似的关系型数据库管理系统。这些系统在某些方面可能与 MySQL 有相似的特性和功能，但也可能在某些方面有所不同。以下是几种常见的与 MySQL 类似的数据处理方案：</p></blockquote><ol><li><strong>MariaDB</strong>：MariaDB 是 MySQL 的一个分支，它由 MySQL 的原始开发者创建，旨在保持与 MySQL 的兼容性，并提供一些新的功能和改进。因此，MariaDB 在很多方面与 MySQL 非常相似，用户可以轻松地迁移和使用 MariaDB。</li><li><strong>PostgreSQL</strong>：PostgreSQL 是另一个流行的开源关系型数据库管理系统，与 MySQL 相比，它在一些方面提供了更丰富和更高级的功能，如支持更复杂的数据类型、更强大的事务支持、更灵活的权限管理等。尤其在处理复杂数据结构和需要高级特性的应用场景下，PostgreSQL 往往是一个很好的选择。</li><li><strong>SQLite</strong>：SQLite 是一个轻量级的嵌入式关系型数据库管理系统，与 MySQL 不同，它不是一个独立的数据库服务器，而是直接嵌入到应用程序中，以库的形式提供。SQLite 适用于一些轻量级的应用场景，如移动应用、桌面应用等，它的特点是简单、易于使用，并且不需要单独的服务器进程。</li><li><strong>Microsoft SQL Server</strong>：Microsoft SQL Server 是微软开发的关系型数据库管理系统，它与 MySQL 相比在某些方面有所不同，比如更紧密地集成到 Microsoft 的生态系统中、提供更多的企业级特性和服务等。Microsoft SQL Server 通常用于 Windows 平台上的企业应用程序。</li></ol>',13)])])}const p=d(s,[["render",l]]);export{h as __pageData,p as default};
